CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY, username TEXT NOT NULL UNIQUE, password_hash TEXT NOT NULL, role TEXT NOT NULL, region TEXT NOT NULL, disabled INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS sessions(id TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL, revoked_at TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS stations(id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, region TEXT NOT NULL, river TEXT NOT NULL, level TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, version INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS samples(id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL REFERENCES stations(id), sampled_at TEXT NOT NULL, quality_class TEXT NOT NULL, metrics_json TEXT NOT NULL, created_by INTEGER NOT NULL REFERENCES users(id), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS alerts(id INTEGER PRIMARY KEY, station_id INTEGER NOT NULL REFERENCES stations(id), sample_id INTEGER REFERENCES samples(id), status TEXT NOT NULL, severity TEXT NOT NULL, opened_at TEXT NOT NULL, closed_at TEXT, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS inspections(id INTEGER PRIMARY KEY, alert_id INTEGER NOT NULL REFERENCES alerts(id), owner_id INTEGER NOT NULL REFERENCES users(id), status TEXT NOT NULL, due_at TEXT NOT NULL, started_at TEXT, completed_at TEXT, notes TEXT NOT NULL DEFAULT '', version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS remediation_actions(id INTEGER PRIMARY KEY, inspection_id INTEGER NOT NULL REFERENCES inspections(id), action TEXT NOT NULL, status TEXT NOT NULL, evidence TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, completed_at TEXT);
CREATE TABLE IF NOT EXISTS agreements(id INTEGER PRIMARY KEY, upstream_region TEXT NOT NULL, downstream_region TEXT NOT NULL, threshold_class TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL, UNIQUE(upstream_region, downstream_region));
CREATE TABLE IF NOT EXISTS warnings(id INTEGER PRIMARY KEY, agreement_id INTEGER NOT NULL REFERENCES agreements(id), station_id INTEGER NOT NULL REFERENCES stations(id), direction TEXT NOT NULL, payload_json TEXT NOT NULL, status TEXT NOT NULL, sent_at TEXT NOT NULL, acknowledged_at TEXT);
CREATE TABLE IF NOT EXISTS compensations(id INTEGER PRIMARY KEY, agreement_id INTEGER NOT NULL REFERENCES agreements(id), period TEXT NOT NULL, direction TEXT NOT NULL, amount_cents INTEGER NOT NULL, reason TEXT NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, settled_at TEXT, UNIQUE(agreement_id, period, direction));
CREATE TABLE IF NOT EXISTS manifests(id INTEGER PRIMARY KEY, manifest_no TEXT NOT NULL UNIQUE, producer_region TEXT NOT NULL, carrier_region TEXT NOT NULL, facility_region TEXT NOT NULL, waste_type TEXT NOT NULL, weight_kg INTEGER NOT NULL, status TEXT NOT NULL, created_at TEXT NOT NULL, accepted_at TEXT, disposed_at TEXT, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS projects(id INTEGER PRIMARY KEY, name TEXT NOT NULL, region TEXT NOT NULL, target_hectares REAL NOT NULL, status TEXT NOT NULL, budget_cents INTEGER NOT NULL, created_at TEXT NOT NULL, version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS milestones(id INTEGER PRIMARY KEY, project_id INTEGER NOT NULL REFERENCES projects(id), name TEXT NOT NULL, target_date TEXT NOT NULL, status TEXT NOT NULL, evidence TEXT NOT NULL DEFAULT '', completed_at TEXT);
CREATE TABLE IF NOT EXISTS audit_events(id INTEGER PRIMARY KEY, actor_id INTEGER REFERENCES users(id), request_id TEXT NOT NULL, object_type TEXT NOT NULL, object_id TEXT NOT NULL, action TEXT NOT NULL, result TEXT NOT NULL, details_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS idempotency_keys(key TEXT PRIMARY KEY, request_hash TEXT NOT NULL, response_json TEXT NOT NULL, created_at TEXT NOT NULL, expires_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_samples_station_time ON samples(station_id, sampled_at DESC);
CREATE INDEX IF NOT EXISTS idx_alerts_status ON alerts(status, opened_at);
CREATE INDEX IF NOT EXISTS idx_manifests_status ON manifests(status, created_at);
CREATE INDEX IF NOT EXISTS idx_audit_object ON audit_events(object_type, object_id, created_at);
